use serde_json::json;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let text = input["text"].as_str().unwrap();
    let shift = input["shift"].as_i64().unwrap();

    let mut result = String::new();

    for c in text.chars() {
        let ascii_val = c as u32;
        let shifted_ascii_val = (ascii_val + shift) % 26;

        let shifted_char = (shifted_ascii_val - 97 + 26) as char;

        result.push(shifted_char);
    }

    json!({
        "text": result,
        "shift": shift
    })
}
